<?php
if(current_user()['role']!=='Admin')throw new Exception('Admin access required.');
echo '<div class="page-head"><div><h1>Product Categories</h1><p>One category list for product creation, editing and filters. Existing SKUs never change when categories change.</p></div></div><div class="card"><h3>Add Main Category / Subcategory</h3><form method="post" action="actions.php" class="form-grid"><input type="hidden" name="action" value="manage_category"><input type="hidden" name="return" value="category_manager"><label>Main Category<input name="main_name" maxlength="100" required></label><label>Subcategory<input name="sub_name" maxlength="100" placeholder="Leave blank for a main category with no children"></label><label><input type="checkbox" name="active" value="1" checked> Active</label><button class="btn primary">Save Category</button></form></div><div class="card table-wrap"><table class="table"><tr><th>Main Category</th><th>Subcategory</th><th>Next New SKU</th><th>Status</th><th>Edit</th></tr>';
foreach(db()->query('SELECT * FROM managed_categories ORDER BY main_name,sub_name') as $c){$seq=category_sequence($c['main_name'],$c['sub_name']);echo '<tr><td>'.e($c['main_name']).'</td><td>'.e($c['sub_name']?:'No subcategory').'</td><td>'.e($seq['prefix'].'-'.str_pad($seq['next_number'],4,'0',STR_PAD_LEFT)).'</td><td>'.($c['active']?'Active':'Inactive').'</td><td><details><summary>Edit</summary><form method="post" action="actions.php" class="stack"><input type="hidden" name="action" value="manage_category"><input type="hidden" name="return" value="category_manager"><input type="hidden" name="category_id" value="'.$c['id'].'"><label>Main Category<input name="main_name" value="'.e($c['main_name']).'" required></label><label>Subcategory<input name="sub_name" value="'.e($c['sub_name']).'"></label><label><input type="checkbox" name="active" value="1" '.($c['active']?'checked':'').'> Active</label><button class="btn secondary">Save Changes</button></form></details></td></tr>';}echo '</table></div>';
